parameters.jsCode:
// 🔹 SAFE INPUT
const input = $json || {};

// 🔹 SAFE BODY
const body = input.body && typeof input.body === "object"
  ? input.body
  : {};

// 🔹 SAFE RAW REQUEST PARSE
let parsed = {};

try {
  if (typeof body.rawRequest === "string") {
    parsed = JSON.parse(body.rawRequest);
  } else if (typeof body.rawRequest === "object") {
    parsed = body.rawRequest;
  }
} catch (e) {
  parsed = {};
}

// 🔹 Extract fields safely
const firstName = parsed?.q4_name?.first || "";
const lastName = parsed?.q4_name?.last || "";

const rawName = `${firstName} ${lastName}`.trim();

const rawEmail = (parsed?.q5_email || "").toString().toLowerCase().trim();

const company = parsed?.q17_companyName || "Unknown";
const leadSource = parsed?.q39_leadSource || "Direct";

// 🔹 Clean name
const cleanName = rawName
  ? rawName
      .split(" ")
      .filter(Boolean)
      .map(w => w.charAt(0).toUpperCase() + w.slice(1).toLowerCase())
      .join(" ")
  : "Unknown";

// 🔹 Email domain
const emailDomain = rawEmail.includes("@")
  ? rawEmail.split("@")[1]
  : "";

// 🔹 PH Timestamp
const phTimestamp = new Date().toLocaleString("en-US", {
  timeZone: "Asia/Manila",
  year: "numeric",
  month: "long",
  day: "numeric",
  hour: "2-digit",
  minute: "2-digit",
  hour12: false
}) + " PHT";

// 🔥 FINAL SAFE OUTPUT
return {
  json: {
    name: cleanName,
    email: rawEmail,
    domain: emailDomain,
    company,
    lead_source: leadSource,
    submitted_at: new Date().toISOString(),
    processed_at: phTimestamp
  }
};

// 🔹 SAFE INPUT (prevents crash)
const data = $json && typeof $json === "object" ? $json : {};

// 🔹 SAFE EXTRACTION (from previous Jotform node)
const lead = data.lead || data;

// ==============================
// 🔍 SAFETY SETUP
// ==============================
const email = (lead.email || "").toString().toLowerCase().trim();
const name = (lead.name || "").toString().trim();
const domain = (lead.domain || "").toString().toLowerCase().trim();
const company = lead.company || "Unknown";
const lead_source = lead.lead_source || "Direct";

// ==============================
// 🔹 RULES
// ==============================
const junkWords = ["test", "fake", "asdf", "none", "spam", "qwerty"];

const personalDomains = [
  "gmail.com",
  "yahoo.com",
  "outlook.com",
  "hotmail.com",
  "icloud.com",
  "msn.com",
];

// ==============================
// 🔹 VALIDATION CHECKS
// ==============================
const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const isValidFormat = emailRegex.test(email);

const isPersonalEmail = personalDomains.includes(domain);

const isJunkLead = junkWords.some((word) => {
  return (
    email.includes(word) ||
    (name && name.toLowerCase().includes(word))
  );
});

const isRealName =
  typeof name === "string" &&
  name.length > 2 &&
  !/\d/.test(name);

// ==============================
// 🔹 FINAL DECISION
// ==============================
const shouldProcess =
  isValidFormat &&
  !isJunkLead &&
  isRealName;

// ==============================
// 🔥 OUTPUT (STRICT n8n FORMAT)
// ==============================
return {
  json: {
    lead: {
      name,
      email,
      domain,
      company,
      lead_source,
      submitted_at: lead.submitted_at || null,
      processed_at: lead.processed_at || null,
    },

    flags: {
      isEmailValid: isValidFormat,
      isPersonalEmail,
      isJunkLead,
      isRealName,
      shouldProcess,
    },
  },
};

const input = $json;

// SAFETY CHECK (prevents crash)
if (!input || typeof input !== "object") {
  return [
    {
      json: {
        error: "Invalid input received",
        raw: input,
      },
    },
  ];
}

// SAFE EXTRACTION
const lead = input.lead || {};
const validation = {
  status: input.status || "unknown",
  free_email: input.free_email || false,
  domain_age_days: input.domain_age_days || 0,
  mx_found: input.mx_found || false,
};

const enrichment = input.data || {};
const person = enrichment.person || {};
const company = enrichment.company || {};

// SCORE
let score = 0;

// EMAIL
if (validation.status === "valid") score += 25;
else if (validation.status === "catch-all") score += 15;

if (validation.mx_found === "true") score += 3;

const domainAge = Number(validation.domain_age_days);
if (domainAge > 3650) score += 5;
else if (domainAge > 1000) score += 3;

if (validation.free_email) score -= 8;

// COMPANY
const employees = company?.metrics?.employees;

if (employees === "11-50") score += 15;
else if (employees === "51-200") score += 22;
else if (employees === "201-1000") score += 26;
else if (employees === "1000+") score += 30;
else score += 8;

// PERSON
const seniority = person?.employment?.seniority;

if (seniority === "executive") score += 25;
else if (seniority === "manager") score += 18;
else score += 6;

// SOURCE
const source = (lead.lead_source || "").toLowerCase();

if (source.includes("referral")) score += 20;
else if (source.includes("website")) score += 17;
else if (source.includes("organic")) score += 15;
else if (source.includes("paid")) score += 10;
else if (source.includes("cold")) score += 5;

// FINAL
const finalScore = Math.max(0, Math.min(100, Math.round(score)));

let priority = "low";
if (finalScore >= 70) priority = "high";
else if (finalScore >= 40) priority = "medium";

// 🔥 CRITICAL: ALWAYS RETURN THIS FORMAT
return [
  {
    json: {
      lead,
      validation,
      enrichment,
      score: finalScore,
      priority,
    },
  },
];
